using System;using System.IO;using System.Security.AccessControl;using System.Security.Principal;using System.Security.Cryptography;using System.Security.Cryptography.X509Certificates;using System.Runtime.InteropServices;using System.Reflection;
static class SetupSecurity {
 public const string SignerHash="__CERT_SHA256__";
 public static SecurityIdentifier Admin=new SecurityIdentifier("S-1-5-32-544"),SystemSid=new SecurityIdentifier("S-1-5-18"),Users=new SecurityIdentifier("S-1-5-32-545");
 [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)] struct FI{public uint size;public string path;public IntPtr file,subject;}
 [StructLayout(LayoutKind.Sequential)] struct TD{public uint size;public IntPtr callback,sip;public uint ui,revocation,choice;public IntPtr file;public uint action;public IntPtr state,url;public uint flags,context;}
 [DllImport("wintrust.dll",ExactSpelling=true,PreserveSig=true)] static extern int WinVerifyTrust(IntPtr window,[MarshalAs(UnmanagedType.LPStruct)] Guid action,ref TD data);
 public static string Hash(Stream s){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
 public static string FileHash(string p){using(var s=File.OpenRead(p))return Hash(s);}
 public static void CheckSelf(){CheckSignature(Assembly.GetExecutingAssembly().Location);}
 public static void CheckSignature(string path){var cert=new X509Certificate2(X509Certificate.CreateFromSignedFile(path));using(var s=new MemoryStream(cert.RawData))if(Hash(s)!=SignerHash)throw new Exception("签名证书不匹配");var f=new FI();f.size=(uint)Marshal.SizeOf(f);f.path=path;IntPtr ptr=Marshal.AllocHGlobal(Marshal.SizeOf(f));try{Marshal.StructureToPtr(f,ptr,false);var d=new TD();d.size=(uint)Marshal.SizeOf(d);d.ui=2;d.choice=1;d.file=ptr;d.flags=0x1000;uint rc=unchecked((uint)WinVerifyTrust(IntPtr.Zero,new Guid("00AAC56B-CD44-11d0-8CC2-00C04FC295EE"),ref d));if(rc!=0&&rc!=0x800B0109)throw new Exception("签名完整性失败："+rc.ToString("X8"));}finally{Marshal.DestroyStructure(ptr,typeof(FI));Marshal.FreeHGlobal(ptr);}}
 public static void NoLinks(string path){for(var p=new DirectoryInfo(path);p!=null;p=p.Parent)if(p.Exists&&(p.Attributes&FileAttributes.ReparsePoint)!=0)throw new Exception("拒绝重解析目录："+p.FullName);if(File.Exists(path)&&(File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new Exception("拒绝重解析文件");}
 public static string Destination(string input){string p=Path.GetFullPath(input.Trim());if(p.StartsWith("\\\\")||p.Equals(Path.GetPathRoot(p),StringComparison.OrdinalIgnoreCase))throw new Exception("请选择本地磁盘中的独立子目录");string windows=Environment.GetFolderPath(Environment.SpecialFolder.Windows);if(p.Equals(windows,StringComparison.OrdinalIgnoreCase)||p.StartsWith(windows+"\\",StringComparison.OrdinalIgnoreCase))throw new Exception("不能安装到 Windows 目录");foreach(string part in p.Split(Path.DirectorySeparatorChar))if(part.Equals("steamapps",StringComparison.OrdinalIgnoreCase)||part.Equals("userdata",StringComparison.OrdinalIgnoreCase))throw new Exception("不能安装到游戏或账号数据目录");foreach(var f in new[]{Environment.SpecialFolder.ProgramFiles,Environment.SpecialFolder.ProgramFilesX86,Environment.SpecialFolder.CommonApplicationData,Environment.SpecialFolder.CommonDesktopDirectory})if(p.Equals(Environment.GetFolderPath(f),StringComparison.OrdinalIgnoreCase))throw new Exception("请选择独立的软件子目录");NoLinks(p);return p;}
 public static void PendingDeletion(string destination){using(var k=Microsoft.Win32.Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Control\Session Manager")){var values=k==null?null:k.GetValue("PendingFileRenameOperations") as string[];if(values==null)return;for(int i=0;i+1<values.Length;i+=2){if(values[i+1]!="")continue;string source=values[i].StartsWith(@"\??\")?values[i].Substring(4):values[i];if(source.Equals(destination,StringComparison.OrdinalIgnoreCase)||source.StartsWith(destination.TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase))throw new Exception("此目录正在等待重启清理，请重启后安装或选择新目录");}}}
 public static string Within(string root,string relative){if(string.IsNullOrWhiteSpace(relative)||relative.Contains(":")||Path.IsPathRooted(relative))throw new Exception("非法相对路径");foreach(string part in relative.Replace('/', '\\').Split('\\'))if(part==".."||part=="."||part.EndsWith(".")||part.EndsWith(" "))throw new Exception("非法相对路径");string target=Path.GetFullPath(Path.Combine(root,relative.Replace('/', '\\')));if(!target.StartsWith(root.TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase))throw new Exception("路径超出安装目录");NoLinks(target);return target;}
 public static void ValidateAcl(string path,bool parent){var sec=Directory.GetAccessControl(path);string owner=((SecurityIdentifier)sec.GetOwner(typeof(SecurityIdentifier))).Value;bool trusted=owner==Admin.Value||owner==SystemSid.Value||(parent&&owner=="S-1-5-80-956008885-3418522649-1831038044-1853292631-2271478464");if(!trusted)throw new Exception("现有目录所有者不可信："+path);foreach(FileSystemAccessRule r in sec.GetAccessRules(true,true,typeof(SecurityIdentifier))){if(r.AccessControlType!=AccessControlType.Allow||(r.PropagationFlags&PropagationFlags.InheritOnly)!=0)continue;string sid=((SecurityIdentifier)r.IdentityReference).Value;if(sid==Admin.Value||sid==SystemSid.Value||sid=="S-1-5-80-956008885-3418522649-1831038044-1853292631-2271478464")continue;var dangerous=FileSystemRights.DeleteSubdirectoriesAndFiles|FileSystemRights.ChangePermissions|FileSystemRights.TakeOwnership;if(!parent)dangerous|=FileSystemRights.Write|FileSystemRights.Delete;if((r.FileSystemRights&dangerous)!=0)throw new Exception("普通用户可以修改或替换目录，请选择管理员控制的位置："+path);}}
 public static void ParentPolicy(string destination){for(var p=new DirectoryInfo(destination).Parent;p!=null;p=p.Parent)if(p.Exists)ValidateAcl(p.FullName,true);}
 public static DirectorySecurity DirectoryPolicy(){var s=new DirectorySecurity();s.SetAccessRuleProtection(true,false);s.SetOwner(Admin);foreach(var sid in new[]{Admin,SystemSid})s.AddAccessRule(new FileSystemAccessRule(sid,FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));s.AddAccessRule(new FileSystemAccessRule(Users,FileSystemRights.ReadAndExecute,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));return s;}
 public static FileSecurity FilePolicy(){var s=new FileSecurity();s.SetAccessRuleProtection(true,false);s.SetOwner(Admin);foreach(var sid in new[]{Admin,SystemSid})s.AddAccessRule(new FileSystemAccessRule(sid,FileSystemRights.FullControl,AccessControlType.Allow));s.AddAccessRule(new FileSystemAccessRule(Users,FileSystemRights.ReadAndExecute,AccessControlType.Allow));return s;}
 public static void MakeDir(string p){NoLinks(p);if(Directory.Exists(p)){ValidateAcl(p,false);return;}string parent=Path.GetDirectoryName(p);if(!Directory.Exists(parent))MakeDir(parent);Directory.CreateDirectory(p,DirectoryPolicy());}
}
